@namespace sv_696ab8ca82604767b5c5c283f845a049.Components.Pages.Settings
@using sv_696ab8ca82604767b5c5c283f845a049.Models

<div class="settings-section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message @(_isError ? "error" : "success")">@_message</div>
        }

        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" @bind="_currentPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="newPwd">New Password</label>
                        <input id="newPwd" type="password" @bind="_newPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" @bind="_confirmPassword" class="form-control" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="security-item">
            <div class="twofa-row">
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
                <label class="toggle-label">
                    <input type="checkbox" @bind="_twoFactorEnabled" class="toggle-input" />
                    <span class="toggle-switch"></span>
                </label>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="hint-text">Last password change: @_lastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != _currentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal-dialog" @onclick:stopPropagation="true">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn btn-danger" @onclick="RevokeConfirmed">Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private string _message = "";
    private bool _isError;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private ActiveSession? _sessionToRevoke;
    private string _currentSessionId = "sess-1"; // First session is "current"

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions.ToList();
        _loading = false;
    }

    private async Task UpdatePassword()
    {
        _isError = false;
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "New password cannot be empty.";
            _isError = true;
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _message = "Passwords do not match.";
            _isError = true;
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _lastPasswordChange = DateTime.UtcNow;
        _message = "Password updated successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeConfirmed()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
            _sessionToRevoke = null;
            _message = "Session revoked.";
            _ = ClearMessageAfterDelay();
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = "";
        await InvokeAsync(StateHasChanged);
    }
}

